# v1: v0 plus retreat-when-in-danger, weakest-target focus fire, safer altar choice
# (away from monoliths), fixed draft chain, and camp claims so allies spread out.

# ---- draft ----
if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
    elif available(pool, champ_tavi()):
        pick(champ_tavi())
    elif available(pool, champ_marcella()):
        pick(champ_marcella())
    elif available(pool, champ_stellar()):
        pick(champ_stellar())
    elif available(pool, champ_ren()):
        pick(champ_ren())
    else:
        pick(random_champion(pool))
    end_turn()

# ---- every turn ----
keep camp_spawns = camp_spawn_tiles()
keep recall_frac = 0.25        # recall when this low, regardless of cargo
keep danger_frac = 0.6         # recall when carrying gems and in danger below this
keep fight_frac = 0.3          # below this, do not start a fresh melee

if not alive() or channeling() or (not can_move() and not can_attack()):
    end_turn()

let at_spawn = contains(spawn_region(ally()), position())
if at_spawn:
    let shards_bought = floor(gold() / 30)
    let strength_shards = floor(shards_bought / 2)
    buy(shard(stat_strength()), strength_shards)
    buy(shard(stat_health()), shards_bought - strength_shards)
    # heal on spawn before heading back out, unless an enemy is already in reach
    if health() < max_health() and not exists(first(filter(enemies_visible(), in_attack_range()))):
        end_turn()

let danger = in_danger()

# retreat: low health always; carrying gems and under fire -> recall and bank
if not at_spawn and (health() < recall_frac * max_health() or (gems() > 0 and danger and health() < danger_frac * max_health())):
    recall()
    end_turn()

# focus fire on the weakest enemy in range
let enemy = weakest(filter(enemies_visible(), in_attack_range()))
if exists(enemy):
    if ability_ready(0):
        cast_at_unit(0, enemy)
    if ability_ready(1):
        cast_at_unit(1, enemy)
    attack(enemy)
    end_turn()

# carrying gems: tribute at an open altar, preferring ones far from monoliths
if gems() > 0:
    let open_altars = minus(altars(), locked_altars())
    let safe_altars = minus(open_altars, ring(monolith_tiles(), 5))
    let altar_here = first(filter(open_altars, within(1, position())))
    if exists(altar_here):
        tribute(altar_here)
        end_turn()
    let safe_goal = closest(safe_altars)
    if exists(safe_goal):
        move_towards(safe_goal)
        end_turn()
    # fallback: any altar, even locked (tributing at a lock attacks it)
    move_towards(closest(ring(altars(), 1)))
    end_turn()

# one camps_visible() query per turn, reused for both attack checks
let camps = camps_visible()

let camp = first(filter(camps, in_attack_range()))
if exists(camp):
    if ability_ready(0):
        cast_at_unit(0, camp)
    if ability_ready(1):
        cast_at_unit(1, camp)
    attack(camp)
    end_turn()

# camp goals: cleared spawns not taken by allies
let goals = minus(minus(camp_spawns, respawning_visible_spawns()), claimed_by_allies())
let goal = closest(goals)

if exists(goal):
    claim(goal)
    # already standing on the goal: hold so the capture timer keeps running
    if position() == goal:
        end_turn()
    move_towards(goal)
    let camp2 = first(filter(camps, in_attack_range()))
    if exists(camp2):
        attack(camp2)
    set_priority(1 + random_int(100))
    end_turn()

# nothing to take: drop claim and wander toward spawn-safe ground
unclaim()
set_priority(1 + random_int(100))
end_turn()

# v1: fixed draft chain (no random picks), treasure-first shard buys,
# recall when hurt and threatened, cleaner goal handling. Based on fs-1.

# ---- draft: deliberate chain, never random unless all preferred picks are gone ----
if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
    elif available(pool, champ_heart_of_ruin()):
        pick(champ_heart_of_ruin())
    elif available(pool, champ_marcella()):
        pick(champ_marcella())
    elif available(pool, champ_vendetta()):
        pick(champ_vendetta())
    elif available(pool, champ_tavi()):
        pick(champ_tavi())
    else:
        pick(random_champion(pool))
    end_turn()

# ---- every turn ----
keep camp_spawns = camp_spawn_tiles()

if not alive() or channeling() or (not can_move() and not can_attack()):
    end_turn()

let at_spawn = contains( spawn_region(ally()), position() )
if at_spawn:
    # Treasure shards first (more gold), split between strength and health
    let shards_bought = floor( gold() / 30 )
    let strength_shards = floor( shards_bought / 2 )
    buy( shard_of(family_treasure(), stat_strength()), strength_shards )
    buy( shard_of(family_treasure(), stat_health()), shards_bought - strength_shards )
    # heal on spawn before heading back out, unless an enemy is already in reach
    if health() < max_health() and not exists(first(filter(enemies_visible(), in_attack_range()))):
        end_turn()

# Retreat: recall at 30% health, or at 50% when carrying gems and under threat
if not at_spawn and (health() < 0.3 * max_health() or (gems() > 0 and in_danger() and health() < 0.5 * max_health())):
    recall()
    end_turn()

# Fight: abilities then basic attack on a visible enemy in range
let enemy = first( filter( enemies_visible(), in_attack_range() ) )
if exists(enemy):
    if ability_ready(0):
        cast_at_unit(0, enemy)
    if ability_ready(1):
        cast_at_unit(1, enemy)
    attack(enemy)
    end_turn()

# Carrying gems: tribute at an open altar, otherwise walk to one
if gems() > 0:
    let open_altars = minus( altars(), locked_altars() )
    let altar = first( filter( open_altars, within(1, position()) ) )
    if exists(altar):
        tribute(altar)
        end_turn()
    move_towards( closest( ring(open_altars, 1) ) )
    end_turn()

# One camps_visible() query per turn, reused for both attack checks
let camps = camps_visible()

let camp = first( filter( camps, in_attack_range() ) )
if exists(camp):
    if ability_ready(0):
        cast_at_unit(0, camp)
    if ability_ready(1):
        cast_at_unit(1, camp)
    attack(camp)
    end_turn()

# Goals: camp spawns not currently respawning
let goals = minus( camp_spawns, respawning_visible_spawns() )

# Already on a cleared camp spawn: hold so the capture timer runs
if contains(goals, position()):
    end_turn()

move_towards( closest(goals) )
let camp2 = first( filter( camps, in_attack_range() ) )
if exists(camp2):
    attack(camp2)
set_priority(1)
end_turn()

# fs-1 v1: fixed draft chain (vesper_vale, tavi, marcella, stellar, ren), Treasure-family shards
# for gold income, named retreat thresholds, tribute at altars away from monoliths when possible,
# and a retreat from in_danger() when hurt.

# ---- tuning constants ----
keep RETREAT_HP = 0.35        # recall when hurt and not carrying gems
keep GEM_RETREAT_HP = 0.55    # recall earlier when carrying gems
keep DANGER_HP = 0.6          # below this, back off when an enemy threatens us

# ---- draft ----
if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
    elif available(pool, champ_tavi()):
        pick(champ_tavi())
    elif available(pool, champ_marcella()):
        pick(champ_marcella())
    elif available(pool, champ_stellar()):
        pick(champ_stellar())
    elif available(pool, champ_ren()):
        pick(champ_ren())
    else:
        pick( random_champion(pool) )
    end_turn()

# ---- every turn ----
keep camp_spawns = camp_spawn_tiles()

if not alive() or channeling() or (not can_move() and not can_attack()):
    end_turn()

let at_spawn = contains( spawn_region(ally()), position() )
if at_spawn:
    let shards_bought = floor( gold() / 30 )
    let strength_shards = floor( shards_bought / 2 )
    # Treasure family first for more gold income, then stat shards
    buy( shard_of(family_treasure(), stat_strength()), strength_shards )
    buy( shard_of(family_treasure(), stat_health()), shards_bought - strength_shards )
    # heal on spawn before heading back out, unless an enemy is already in reach
    if health() < max_health() and not exists(first(filter(enemies_visible(), in_attack_range()))):
        end_turn()

# recall when badly hurt, earlier when carrying gems
if not at_spawn and (health() < RETREAT_HP * max_health() or (gems() > 0 and health() < GEM_RETREAT_HP * max_health())):
    recall()
    end_turn()

let enemy = first( filter( enemies_visible(), in_attack_range() ) )
if exists(enemy):
    if ability_ready(0):
        cast_at_unit(0, enemy)
    if ability_ready(1):
        cast_at_unit(1, enemy)
    attack(enemy)
    end_turn()

# hurt and under threat: step back toward spawn instead of trading blows
if health() < DANGER_HP * max_health() and in_danger() and not at_spawn:
    move_towards( closest( spawn_region(ally()) ) )
    end_turn()

if gems() > 0:
    let open_altars = minus( altars(), locked_altars() )
    let safe_altars = minus( open_altars, ring(monolith_tiles(), 5) )
    # prefer altars away from monoliths; fall back to any open altar
    if exists(first(safe_altars)):
        let adj_safe = first( filter( safe_altars, within(1, position()) ) )
        if exists(adj_safe):
            tribute(adj_safe)
            end_turn()
        move_towards( closest( ring(safe_altars, 1) ) )
        end_turn()
    let adj_open = first( filter( open_altars, within(1, position()) ) )
    if exists(adj_open):
        tribute(adj_open)
        end_turn()
    move_towards( closest( ring(open_altars, 1) ) )
    end_turn()

# one camps_visible() query per turn, reused for both attack checks
let camps = camps_visible()

let camp = first( filter( camps, in_attack_range() ) )
if exists(camp):
    if ability_ready(0):
        cast_at_unit(0, camp)
    if ability_ready(1):
        cast_at_unit(1, camp)
    attack(camp)
    end_turn()

let goals = minus( camp_spawns, respawning_visible_spawns() )

# already standing on a cleared camp spawn: hold here so the capture timer keeps running
if contains(goals, position()):
    end_turn()

move_towards( closest(goals) )
let camp2 = first( filter( camps, in_attack_range() ) )
if exists(camp2):
    attack(camp2)
set_priority( 1 + random_int(100) )
end_turn()

# v1: fixed draft chain, treasure shards, focus-fire the weakest visible enemy with
# damage abilities only, retreat when hurt and in danger, and tribute in larger bags.

# ---- draft: deliberate fixed order, never random while a listed pick is open ----
if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
    elif available(pool, champ_tavi()):
        pick(champ_tavi())
    elif available(pool, champ_marcella()):
        pick(champ_marcella())
    elif available(pool, champ_stellar()):
        pick(champ_stellar())
    elif available(pool, champ_ren()):
        pick(champ_ren())
    elif available(pool, champ_heart_of_ruin()):
        pick(champ_heart_of_ruin())
    else:
        pick( random_champion(pool) )
    end_turn()

# ---- every turn ----
keep camp_spawns = camp_spawn_tiles()

if not alive() or channeling() or (not can_move() and not can_attack()):
    end_turn()

let at_spawn = contains( spawn_region(ally()), position() )
