    # Treasure shards first (more gold), split between strength and health
    let shards_bought = floor( gold() / 30 )
    let strength_shards = floor( shards_bought / 2 )
    buy( shard_of(family_treasure(), stat_strength()), strength_shards )
    buy( shard_of(family_treasure(), stat_health()), shards_bought - strength_shards )
    # heal on spawn before heading back out, unless an enemy is already in reach
    if health() < max_health() and not exists(first(filter(enemies_visible(), in_attack_range()))):
        end_turn()

# retreat: recall when low, or when hurt and something can reach us (carrying or not)
if not at_spawn and (health() < 0.2 * max_health() or (gems() > 0 and health() < 0.5 * max_health())):
    recall()
    end_turn()

if not at_spawn and health() < 0.4 * max_health() and in_danger():
    move_towards(closest(spawn_region(ally())))
    end_turn()

# fight: focus the weakest visible enemy in range, use only damage/stun abilities on it
let enemy = weakest( filter( enemies_visible(), in_attack_range() ) )
if exists(enemy):
    if ability_ready(0) and (slot_is_damage(0) or slot_is_stun(0)):
        cast_at_unit(0, enemy)
    if ability_ready(1) and (slot_is_damage(1) or slot_is_stun(1)):
        cast_at_unit(1, enemy)
    attack(enemy)
    end_turn()

# tribute: carry bigger bags, but tribute early when hurt or when enemies are about
if gems() > 0 and (gems() >= 8 or health() < 0.5 * max_health() or exists(first(enemies_visible()))):
    let open_altars = minus( altars(), locked_altars() )
    let altar = first( filter( open_altars, within(1, position()) ) )
    if exists(altar):
        tribute(altar)
        end_turn()
    move_towards( closest( ring(open_altars, 1) ) )
    end_turn()

# one camps_visible() query per turn, reused for both attack checks
let camps = camps_visible()

let camp = weakest( filter( camps, in_attack_range() ) )
if exists(camp):
    if ability_ready(0) and (slot_is_damage(0) or slot_is_aoe(0)):
        cast_at_unit(0, camp)
    if ability_ready(1) and (slot_is_damage(1) or slot_is_aoe(1)):
        cast_at_unit(1, camp)
    attack(camp)
    end_turn()

